// The `.` entry of `pkg_bare`, named by the `nish` condition of its `exports`.
// `helper` is private to the package and shares its name with two others in
// this program; `./util` is imported relatively from inside the package, which
// is how a dependency's own modules stay in their dependency's package.
import { twice } from "./util";

const helper = (n: i32): i32 => n + 1;

export const scale = (n: i32): i32 => twice(helper(n));
